def max_profit(prices):
    n = len(prices)
    max_after = [0] * n   # highest price from day i to the end
    max_after[-1] = prices[-1]
    for i in range(n - 2, -1, -1):
        max_after[i] = max(prices[i], max_after[i + 1])

    return max(max_after[i] - prices[i] for i in range(n))

